INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(1801, 'Exodus 12:46', 'Exodus', 12, 46, '&nbsp;دا ټول خوراک به په هغه کور کښې خوړلے شى چې په کوم کښې دا تيار شوے وى، چې غوښه بهر راونۀ باسئ او چې يو هډُوکے هم مات نۀ کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1802, 'Exodus 12:47', 'Exodus', 12, 47, '&nbsp;د بنى اِسرائيلو ټول قوم به دا اختر کوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1803, 'Exodus 12:48', 'Exodus', 12, 48, '&nbsp;خو چې کوم سړے سنت شوے نۀ وى هغه به دا نۀ خورى. کۀ په تاسو کښې د بل مُلک څوک اوسيږى او د مالِک خُدائ په درناوى کښې د فسحې اختر کول غواړى، نو اول به خامخا د هغۀ د کور ټول نران سنت کولے شى. بيا به هغه د يو پېدائشى بنى اِسرائيلى په شان ګڼلے شى او په دې اختر کښې تاسو سره برخه اخستے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1804, 'Exodus 12:49', 'Exodus', 12, 49, '&nbsp;د هغه مُلک او د بل مُلک خلقو دپاره به يو شان قانون وى کوم چې ستاسو سره اوسيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1805, 'Exodus 12:50', 'Exodus', 12, 50, '&nbsp;ټولو بنى اِسرائيلو فرمانبردارى وکړه او هم هغه شان يې وکړل چې څنګه مالِک خُدائ موسىٰ او هارون له حُکم ورکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1806, 'Exodus 12:51', 'Exodus', 12, 51, '&nbsp;هم په هغه ورځ مالِک خُدائ د بنى اِسرائيلو قبيلې د مِصر د مُلک نه راوويستلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1807, 'Exodus 13:1', 'Exodus', 13, 1, '&nbsp;بيا مالِک خُدائ موسىٰ ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1808, 'Exodus 13:2', 'Exodus', 13, 2, '&nbsp;”ټول وړومبى پېدا شوى نران ما ته وقف کړه. د هرې بنى اِسرائيلۍ ښځې مشر ماشوم او هر يو وړومبے نر څاروے زما دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1809, 'Exodus 13:3', 'Exodus', 13, 3, '&nbsp;موسىٰ خلقو ته وفرمائيل، ”دا ورځ ياده ساتئ، په کومه ورځ چې تاسو د مِصر نه راووتلئ، چرته چې تاسو غلامان وئ، دا هغه ورځ ده چې مالِک خُدائ تاسو د خپل لوئ طاقت سره راوويستلئ، خمبيره روټۍ به نۀ خورئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1810, 'Exodus 13:4', 'Exodus', 13, 4, '&nbsp;د وړومبۍ مياشتې په دې ورځ چې د ابيب مياشت ده تاسو د مِصر نه روان يئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1811, 'Exodus 13:5', 'Exodus', 13, 5, '&nbsp;مالِک خُدائ ستاسو د پلار نيکۀ سره پوخ لوظ کړے دے چې تاسو له به د کنعانيانو، حِتيانو، اموريانو، حِويانو او د يبوسيانو مُلک درکوى. چې کله تاسو هغه زرخېز مُلک ته بوځى، نو د کال په وړومبۍ مياشت کښې دا اختر کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1812, 'Exodus 13:6', 'Exodus', 13, 6, '&nbsp;اووۀ ورځې به تاسو پتيره روټۍ خورئ او په اوومه ورځ د مالِک خُدائ د درناوى دپاره اختر وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1813, 'Exodus 13:7', 'Exodus', 13, 7, '&nbsp;اووۀ ورځې به تاسو خمبيره روټۍ نۀ خورئ، چې خمبيره روټۍ هيچرته هم ستاسو په مُلک کښې پېدا نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1814, 'Exodus 13:8', 'Exodus', 13, 8, '&nbsp;چې کله اختر شروع کيږى، خپلو زامنو ته ووايئ چې دا هر څۀ تاسو ځکه کوئ چې کله تاسو د مِصر نه تلئ نو مالِک خُدائ ستاسو دپاره څۀ کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1815, 'Exodus 13:9', 'Exodus', 13, 9, '&nbsp;چې کله تاسو دا اختر کوئ نو دا به تاسو ته هغه څۀ داسې دريادوى لکه چې يوه نښه تاسو په خپل لاس يا تندى تړلى وى، نو د دې دپاره چې د مالِک خُدائ کلام ستاسو په ژبه وى، ځکه چې مالِک خُدائ د خپل لوئ طاقت سره تاسو د مِصر نه راوويستلئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1816, 'Exodus 13:10', 'Exodus', 13, 10, '&nbsp;نو تاسو هر کال دا اختر په خپل مقرر وخت کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1817, 'Exodus 13:11', 'Exodus', 13, 11, '&nbsp;مالِک خُدائ به تاسو د کنعانيانو مُلک ته راولى، د کوم چې هغۀ ستاسو پلار نيکۀ له د ورکولو پوخ لوظ کړے دے. چې کله هغه مُلک تاسو له درکړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1818, 'Exodus 13:12', 'Exodus', 13, 12, '&nbsp;نو تاسو خامخا هر وړومبے پېدا شوے نر مالِک خُدائ ته پېش کوئ. ستاسو هر يو وړومبے پېدا شوے نر څاروے به د مالِک خُدائ وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1819, 'Exodus 13:13', 'Exodus', 13, 13, '&nbsp;خو تاسو به د هغۀ نه هر يو نر خر واپس اخلئ او د هغۀ په بدل کښې به يو ګډُورے پېش کوئ. خو کۀ تاسو هغه خر واپس اخستل نۀ غواړئ، نو څټ يې مات کړئ. تاسو به هر يو خپل وړومبے پېدا شوے نر بچے په بدل کښې خامخا واپس اخلئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1820, 'Exodus 13:14', 'Exodus', 13, 14, '&nbsp;په راتلونکى وخت کښې چې کله ستاسو زامن تپوس کوى چې د دې رسمونو څۀ مطلب دے، نو تاسو به ورته وايئ چې مالِک خُدائ په خپل لوئ طاقت سره مونږ د مِصر نه راوويستلو، چې هلته مونږ غلامان وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1821, 'Exodus 13:15', 'Exodus', 13, 15, '&nbsp;چې کله د مِصر فِرعون خپل زړۀ سخت کړو او مونږ يې تلو ته نۀ پرېښودلو، نو مالِک خُدائ د مِصر په مُلک کښې هر يو وړومبے پېدا شوے نر انسان او حېوان ووژلو. نو دا ځکه مونږ هر يو نر څاروے مالِک خُدائ ته قربانى کوُو او خپل وړومبى پېدا شوى زامن په بدل کښې واپس اخلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1822, 'Exodus 13:16', 'Exodus', 13, 16, '&nbsp;دا اختر به يو يادګار وى، داسې لکه چې مونږ يوه نښه په خپل لاس يا تندى باندې تړلې وى، دا به مونږ ته هغه څۀ رايادوى چې مالِک خُدائ په خپل لوئ طاقت سره مونږ د مِصر نه راوويستلو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1823, 'Exodus 13:17', 'Exodus', 13, 17, '&nbsp;چې کله د مِصر فِرعون خلق تلو ته پرېښودل، نو خُدائ پاک دوئ په هغه لار بونۀ تلل کومه چې د درياب په غاړه د فلستيانو علاقې ته تلې وه، اګر چې دا لار لنډه وه. خُدائ پاک وفرمائيل، ”زۀ دا نۀ غواړم چې دا خلق پښېمانه شى او مِصر ته راواپس شى چې هغوئ ته دا پته ولګى چې په هغوئ جنګ راروان دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1824, 'Exodus 13:18', 'Exodus', 13, 18, '&nbsp;نو هغۀ دا خلق د صحرا په کږه وږه لار د بحرِقُلزم په طرف بوتلل. بنى اِسرائيلو د جنګ دپاره قطارونه جوړ کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1825, 'Exodus 13:19', 'Exodus', 13, 19, '&nbsp;موسىٰ د يوسف هډُوکى د خپل ځان سره يوړل، لکه څنګه چې يوسف د بنى اِسرائيلو نه د دې د وړلو پوخ لوظ اخستے وو. يوسف فرمائيلى وُو، ”خُدائ پاک به په رښتيا سره ستاسو مدد له راشى، نو بيا تاسو خامخا زما هډُوکى د دې ځائ نه د خپل ځان سره يوسئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1826, 'Exodus 13:20', 'Exodus', 13, 20, '&nbsp;بنى اِسرائيل د سُکات نه لاړل او د صحرا په غاړه ايتام کښې يې خېمې ولګولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1827, 'Exodus 13:21', 'Exodus', 13, 21, '&nbsp;د ورځې به مالِک خُدائ د وريځې په ستن کښې د لار ښودلو دپاره د دوئ نه مخکښې تلو او د شپې د اور په ستن کښې مخکښې تلو چې دوئ ته رڼا وى او چې دوئ د شپې، ورځې مزل کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1828, 'Exodus 13:22', 'Exodus', 13, 22, '&nbsp;د ورځې به هر وخت د وريځې ستن د خلقو نه مخکښې وه او د شپې به د اور ستن د هغوئ نه مخکښې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1829, 'Exodus 14:1', 'Exodus', 14, 1, '&nbsp;بيا مالِک خُدائ موسىٰ ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1830, 'Exodus 14:2', 'Exodus', 14, 2, '&nbsp;”بنى اِسرائيلو ته ووايه چې واپس راوګرځى او فى‌هخيروت ته مخامخ، د مجدال او د درياب په مينځ کښې بعل‌صفون ته نزدې خېمې ولګوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1831, 'Exodus 14:3', 'Exodus', 14, 3, '&nbsp;د فِرعون به دا خيال وى چې بنى اِسرائيل په مُلک کښې سرګردانه ګرځى او په صحرا کښې راګېر دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1832, 'Exodus 14:4', 'Exodus', 14, 4, '&nbsp;زۀ به د فِرعون زړۀ سخت کړم او هغه به په دوئ پسې وى، خو زۀ به د فِرعون او د هغۀ په ټول لښکر فتح ومومم نو داسې به زما عزت وشى، او مِصريانو ته به پته ولګى چې زۀ مالِک خُدائ يم.“ نو بنى اِسرائيلو فرمانبردارى وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1833, 'Exodus 14:5', 'Exodus', 14, 5, '&nbsp;چې کله فِرعون خبر شو چې بنى اِسرائيل تښتېدلى دى، نو هغۀ او د هغۀ درباريانو خپلې ارادې بدلې کړې او وې وئيل، ”مونږ دا څۀ کړى دى؟ مونږ بنى اِسرائيل تښتېدلو ته پرېښودل، زمونږ غلامان زمونږ د لاس نه لاړل.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1834, 'Exodus 14:6', 'Exodus', 14, 6, '&nbsp;نو فِرعون خپلې جنګى ګاډۍ تيارې کړې او خپل لښکر يې د ځان سره روان کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1835, 'Exodus 14:7', 'Exodus', 14, 7, '&nbsp;هغه د خپلو ټولو جنګى ګاډو سره روان شو، شپږ سوه په کښې ښې ښې جنګى ګاډۍ وې چې آفسران ورسره وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1836, 'Exodus 14:8', 'Exodus', 14, 8, '&nbsp;مالِک خُدائ د فِرعون زړۀ سخت کړو او هغه په بنى اِسرائيلو پسې روان شو نو بنى اِسرائيل زړَور روان وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1837, 'Exodus 14:9', 'Exodus', 14, 9, '&nbsp;د مِصريانو لښکر، سره د ټولو آسونو، جنګى ګاډو او په آسونو سوارۀ کسان په دوئ پسې وُو او هلته ور ورسېدل چرته يې د درياب سره فى‌هخيروت او بعل‌صفون ته نزدې خېمې لګولې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1838, 'Exodus 14:10', 'Exodus', 14, 10, '&nbsp;چې څنګه فِرعون ورلنډ شو، نو بنى اِسرائيلو وکتل، او وې ليدل چې مِصريان په دوئ پسې راروان وُو. بنى اِسرائيل ډېر سخت ويرېدل او مالِک خُدائ ته يې فرياد وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1839, 'Exodus 14:11', 'Exodus', 14, 11, '&nbsp;دوئ موسىٰ ته ووئيل، ”په مِصر کښې اديرې نۀ وې څۀ چې تا دې صحرا ته د مړ کېدو دپاره راوستلى يُو؟ ګوره، دا تا څۀ کړى دى چې مونږ دې د مِصر نه راوويستلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1840, 'Exodus 14:12', 'Exodus', 14, 12, '&nbsp;مونږ تا ته مخکښې په مِصر کښې نۀ وُو وئيلى چې داسې به کيږى؟ مونږ تا ته وئيلى وُو چې مونږ پرېږده چې د مِصريانو غلامى کوُو. چې په دې صحرا کښې د مړۀ کېدو نه به ښۀ وى چې مونږ د مِصريانو غلامى کولے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1841, 'Exodus 14:13', 'Exodus', 14, 13, '&nbsp;موسىٰ ورته په جواب کښې وفرمائيل، ”يرېږئ مه. کلک شئ،او تاسو به وګورئ چې مالِک خُدائ ستاسو د بچ کولو دپاره نن څۀ کوى، ځکه چې نن تاسو کوم مِصريان وينئ هغوئ به هيڅکله هم بيا ونۀ وينئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1842, 'Exodus 14:14', 'Exodus', 14, 14, '&nbsp;مالِک خُدائ به ستاسو دپاره جګړه وکړى، تاسو غلى کښېنئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1843, 'Exodus 14:15', 'Exodus', 14, 15, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل، ”تۀ ولې ما ته ژاړې؟ بنى اِسرائيلو ته ووايه چې وړاندې لاړ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1844, 'Exodus 14:16', 'Exodus', 14, 16, '&nbsp;خپله امسا پورته کړه او د درياب دپاسه يې ونيسه. اوبۀ به په مينځ بېلې شى او بنى اِسرائيل به د درياب په مينځ کښې په اوچه زمکه پورې وځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1845, 'Exodus 14:17', 'Exodus', 14, 17, '&nbsp;زۀ به د مِصريانو زړونه دومره سخت کړم چې هغوئ به په تاسو پسې درشى، نو په فِرعون، د هغۀ په لښکر، جنګى ګاډو او د هغۀ په آسونو سوارو کسانو فتح موندلو په وجه به زما عزت وشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1846, 'Exodus 14:18', 'Exodus', 14, 18, '&nbsp;چې کله زۀ هغوئ له ماتے ورکړم، نو مِصريانو ته به پته ولګى چې زۀ مالِک خُدائ يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1847, 'Exodus 14:19', 'Exodus', 14, 19, '&nbsp;د مالِک خُدائ فرښته، کومه چې د بنى اِسرائيلو د لښکر نه مخکښې روانه وه، اوس د دوئ شاته لاړه. د وريځې ستن هم حرکت وکړو تر دې پورې', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1848, 'Exodus 14:20', 'Exodus', 14, 20, '&nbsp;چې د مِصريانو او بنى اِسرائيلو په مينځ کښې شوه. وريځې به مِصريانو ته تيارۀ جوړوله، خو د بنى اِسرائيلو لښکر ته به يې رڼا راوستله، نو دا لښکرې په ټوله شپه کښې يو بل ته نزدې نۀ شوې راتلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1849, 'Exodus 14:21', 'Exodus', 14, 21, '&nbsp;نو موسىٰ د درياب دپاسه خپل لاس اوږد کړو او مالِک خُدائ د نمرخاتۀ په زورَوره هوا درياب وروستو بوتلو. هوا ټوله شپه وچلېدله او درياب يې په اوچه زمکه بدل کړو. اوبۀ په مينځ بېلې شوې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1850, 'Exodus 14:22', 'Exodus', 14, 22, '&nbsp;او بنى اِسرائيل په اوچه زمکه د درياب نه پورې وتل، د دوئ ښى او ګس طرف ته د اوبو دېوالونه وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1851, 'Exodus 14:23', 'Exodus', 14, 23, '&nbsp;مِصريان ورپسې وُو او د خپلو ټولو آسونو، جنګى ګاډو او په آسونو سوارو کسانو سره په دوئ پسې درياب ته ورکوز شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1852, 'Exodus 14:24', 'Exodus', 14, 24, '&nbsp;د سحر د رڼا نه مخکښې مالِک خُدائ د اور او وريځې ستن نه لاندې د مِصريانو لښکر ته وکتل او هغوئ يې د وارخطايۍ په وجه تښتېدو ته جوړ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1853, 'Exodus 14:25', 'Exodus', 14, 25, '&nbsp;مالِک خُدائ د هغوئ د جنګى ګاډو پايې ونښلولې، نو چې هغه په سختۍ سره چلېدلې. مِصريانو ووئيل، ”مالِک خُدائ زمونږ خِلاف د بنى اِسرائيلو دپاره جګړه کوى. راځئ چې د بنى اِسرائيلو نه وتښتُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1854, 'Exodus 14:26', 'Exodus', 14, 26, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل، ”خپل لاس د درياب دپاسه اوږد کړه، نو اوبۀ به په مِصريانو، د هغوئ په جنګى ګاډو او په آسونو سوارو کسانو واپس راشى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1855, 'Exodus 14:27', 'Exodus', 14, 27, '&nbsp;نو موسىٰ خپل لاس د درياب دپاسه اوږد کړو او د سحر د رڼا په وخت اوبۀ خپل صحيح ځائ له واپس راغلې. مِصريانو د اوبو نه د تښتېدو کوشش وکړو، خو مالِک خُدائ هغوئ د درياب مينځ ته ورګزار کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1856, 'Exodus 14:28', 'Exodus', 14, 28, '&nbsp;اوبۀ واپس راغلې او جنګى ګاډۍ، په آسونو سوارۀ کسان او د مِصريانو ټول لښکر اوبو ډُوب کړو کوم چې د درياب پورې په بنى اِسرائيلو پسې وُو، او يو هم پکښې بچ پاتې نۀ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1857, 'Exodus 14:29', 'Exodus', 14, 29, '&nbsp;خو بنى اِسرائيل په اوچه زمکه د درياب نه پورې وتل او د دوئ ښى او ګس طرف ته د اوبو دېوالونه وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1858, 'Exodus 14:30', 'Exodus', 14, 30, '&nbsp;نو، په هغه ورځ مالِک خُدائ بنى اِسرائيل د مِصريانو د زور نه بچ کړل او بنى اِسرائيلو هغوئ وليدل چې د درياب په غاړه مړۀ پراتۀ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1859, 'Exodus 14:31', 'Exodus', 14, 31, '&nbsp;چې کله بنى اِسرائيلو د مالِک خُدائ هغه لوئ قُدرت وليدو کوم چې هغۀ د مِصريانو خِلاف ښودلے وو، نو دوئ د مالِک خُدائ نه ويرېدل، او په مالِک خُدائ او د هغۀ په خِدمت کوونکى موسىٰ يې ايمان راوړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1860, 'Exodus 15:1', 'Exodus', 15, 1, '&nbsp;بيا موسىٰ او بنى اِسرائيلو مالِک خُدائ ته دا حمد‌و‌ثناء ووئيله، ”زۀ به مالِک خُدائ دپاره حمد‌و‌ثناء ووايم، ځکه چې هغۀ د جلال نه ډکه فتح موندلې ده، هغۀ آسونه او په آسونو سوارۀ کسان درياب ته غورزولى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1861, 'Exodus 15:2', 'Exodus', 15, 2, '&nbsp;مالِک خُدائ زما طاقت دے او زما حمد‌و‌ثناء د هغۀ دپاره ده، او هغه ذات دے چې زۀ يې بچ کړے يم، هغه زما خُدائ پاک دے او زۀ به د هغۀ ثناء وايم، هغه زما د پلار خُدائ پاک دے او زۀ به د هغۀ لوئى بيان کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1862, 'Exodus 15:3', 'Exodus', 15, 3, '&nbsp;مالِک خُدائ د جنګيالى په شان دے، د هغۀ نوم مالِک خُدائ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1863, 'Exodus 15:4', 'Exodus', 15, 4, '&nbsp;هغۀ درياب کښې د فِرعون جنګى ګاډۍ او لښکر ډُوب کړو د هغۀ ښۀ ښۀ مشران په بحرِقُلزم کښې ډُوب شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1864, 'Exodus 15:5', 'Exodus', 15, 5, '&nbsp;ژور درياب هغوئ ډُوب کړل، هغوئ د کاڼى په شان لاندې بېخ ته لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1865, 'Exodus 15:6', 'Exodus', 15, 6, '&nbsp;مالِکه خُدايه، ستا په ښى لاس کښې د جلال نه ډک طاقت شته، مالِکه خُدايه، ستا ښے لاس دشمنان ټوټې ټوټې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1866, 'Exodus 15:7', 'Exodus', 15, 7, '&nbsp;د خپل لوئ جلال سره تا خپل دشمنان د پښو لاندې کړل، تا د اور په شان خپل قهر ورولېږلو او هغوئ دې د بوسو په شان وسوزول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1867, 'Exodus 15:8', 'Exodus', 15, 8, '&nbsp;تا درياب پو کړو او اوبۀ اوچتې راغونډې شوې، سېلابونه د دېوال په شان نېغ ودرېدل، او د درياب په بېخ کښې اوبۀ کلکې شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1868, 'Exodus 15:9', 'Exodus', 15, 9, '&nbsp;دشمن لافې وهلې، چې زۀ به په هغوئ پسې يم او زۀ به ورورسېږم، زۀ به د هغوئ غنيمت ووېشم او خپل ځان به په دې ښۀ موړ کړم. زۀ به خپله تُوره راوباسم او زۀ به هغوئ تباه کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1869, 'Exodus 15:10', 'Exodus', 15, 10, '&nbsp;خو تا پوکے ورکړو او درياب هغوئ ډُوب کړل، مِصريان په زورَورو اوبو کښې د سيکې په شان ډُوب شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1870, 'Exodus 15:11', 'Exodus', 15, 11, '&nbsp;اے مالِکه خُدايه، ستا په شان نور معبودان څوک دى؟ ستا په شان څوک دے چې ټولو نه لوئ او مقدس دے؟ ستا جلال د يرې نه ډک دے، ځکه چې داسې عجيبه عجيبه کارونه کوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1871, 'Exodus 15:12', 'Exodus', 15, 12, '&nbsp;تا خپل ښے لاس اوږد کړو، نو زمکې زمونږ دشمنان ژوندى تېر کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1872, 'Exodus 15:13', 'Exodus', 15, 13, '&nbsp;تۀ په خپله وعده ولاړ وې او تا هغه خلقو ته لار ښودله کوم چې تا بچ کړى دى، تۀ به په خپل طاقت سره هغوئ، تر خپل مقدس ځائ پورې ورسوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1873, 'Exodus 15:14', 'Exodus', 15, 14, '&nbsp;قومونو واورېدل او په لړزان شول، فلستيان په دردونو آخته شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1874, 'Exodus 15:15', 'Exodus', 15, 15, '&nbsp;د ادوم مشران ويرېدل، د موآب مشران په لړزان آخته شول، د کنعان ټولو اوسېدونکو خپله حوصله بائيلله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1875, 'Exodus 15:16', 'Exodus', 15, 16, '&nbsp;سخته يره او هيبت په هغوئ باندې پرېوتو، هغوئ ستا د لاس طاقت وليدو او هغوئ د تيږې په شان غلى شول، تر دې پورې مالِکه خُدايه، چې ستا قوم تېر شولو، چې هغه خلق تېر شول کوم چې تا بچ کول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1876, 'Exodus 15:17', 'Exodus', 15, 17, '&nbsp;تۀ به خپل خلق دننه راولې او هغوئ به په خپل غرۀ آبادوې، هغه ځائ اے مالِکه خُدايه، چې تا د خپل ځان دپاره خوښ کړے دے، هغه پاک ځائ ته، اے مالِکه خُدايه، چې تا په خپله ودان کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1877, 'Exodus 15:18', 'Exodus', 15, 18, '&nbsp;مالِک خُدائ به تل تر تله بادشاهى کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1878, 'Exodus 15:19', 'Exodus', 15, 19, '&nbsp;چې کله د فِرعون آسونه، د هغۀ جنګى ګاډۍ او د هغۀ په آسونو سوارۀ کسان درياب ته ورکوز شول، مالِک خُدائ د درياب اوبۀ واپس په هغوئ باندې راوستلې، خو بنى اِسرائيل د درياب په مينځ کښې په اوچه زمکه تېر شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1879, 'Exodus 15:20', 'Exodus', 15, 20, '&nbsp;بيا د هارون خور مريم، کومه چې پېغمبره وه، هغې خپل تمبل راواخستلو، او ټولې ښځې د خپلو تمبلونو سره په ګډېدو په هغې پسې لاړلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1880, 'Exodus 15:21', 'Exodus', 15, 21, '&nbsp;نو مريم هغوئ ته دا حمد‌و‌ثناء ووئيله، ”مالِک خُدائ ته حمد‌و‌ثناء ووايئ، ځکه چې هغۀ لويه فتح موندلې ده، هغۀ آسونه او په آسونو سوارۀ کسان درياب ته غورزولى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1881, 'Exodus 15:22', 'Exodus', 15, 22, '&nbsp;بيا موسىٰ بنى اِسرائيلو له حُکم ورکړو چې د بحرِقُلزم نه روان شى، نو دوئ د شور صحرا ته لاړل. دوئ په صحرا کښې درې ورځې مزل وکړو خو اوبۀ يې ونۀ موندلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1882, 'Exodus 15:23', 'Exodus', 15, 23, '&nbsp;چې کله دوئ ماره ته راغلل، نو دوئ د ماره اوبۀ نۀ شوې څښلے ځکه چې د دې ځائ اوبۀ ترخې وې. نو د دې ځائ نوم ماره اېښودلے شوے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1883, 'Exodus 15:24', 'Exodus', 15, 24, '&nbsp;نو خلق موسىٰ ته وغورېدل او ورته يې ووئيل، ”مونږ به څۀ څښو؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1884, 'Exodus 15:25', 'Exodus', 15, 25, '&nbsp;موسىٰ مالِک خُدائ ته سوال وکړو، نو مالِک خُدائ هغۀ ته د لرګى يوه ټُکړه وښودله، هغۀ دا اوبو ته وغورزوله او اوبۀ خوږې شوې. مالِک خُدائ هلته د هغوئ دپاره حُکمونه او يو قانون جوړ کړو او هلته يې په هغوئ آزمېښت وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1885, 'Exodus 15:26', 'Exodus', 15, 26, '&nbsp;ورته يې وفرمائيل، ”کۀ تاسو د مالِک خُدائ، د خپل خُدائ پاک خبره په غور سره واورئ او هغه څۀ کوئ کوم چې د هغۀ په نظر کښې صحيح دى او د هغۀ قانون ته پام کوئ او د هغۀ ټول حُکمونه پوره کوئ، نو زۀ به په تاسو داسې هيڅ بيمارۍ نۀ راولم چې کومې ما په مِصريانو راوستلې وې، ځکه چې زۀ مالِک خُدائ يم او زۀ شفا درکوونکے يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1886, 'Exodus 15:27', 'Exodus', 15, 27, '&nbsp;بيا دوئ ايليم ته راغلل، چې هلته د اوبو دولس چينې او د کجورو اويا ونې وې، او هلته هغوئ د اوبو په خوا خېمې ولګولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1887, 'Exodus 16:1', 'Exodus', 16, 1, '&nbsp;د بنى اِسرائيلو ټول قوم د ايليم نه په سفر روان شو او د دوېمې مياشتې په پينځلسمه ورځ دوئ د صين بيابان ته راغلل، دا د هغوئ د مِصر نه د راوتلو نه پس وُو، کوم چې د ايليم او سينا په مينځ کښې دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1888, 'Exodus 16:2', 'Exodus', 16, 2, '&nbsp;هلته په بيابان کښې دوئ ټول د موسىٰ او هارون خِلاف وغورېدل', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1889, 'Exodus 16:3', 'Exodus', 16, 3, '&nbsp;او بنى اِسرائيلو هغوئ ته ووئيل، ”کاش چې مونږ مالِک خُدائ د مِصر په مُلک کښې وژلى وے. هلته د غوښې لوښو ته کښېناستے خو شُو کنه چې مونږ په مړه خېټه روټۍ خوړلے. تاسو مونږ دلته دې بيابان ته د دې دپاره راوستلى يُو چې دا ټول خلق د لوږې نه ووژنئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1890, 'Exodus 16:4', 'Exodus', 16, 4, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل، ”ګوره، اوس به زۀ ستاسو ټولو دپاره د آسمان نه يو خوراک د باران په شان ووروم. دا خلق دې هره ورځ بهر ځى او د ځان دپاره دې هم هغه هومره راټولوى چې بس يې وى. نو داسې به زۀ دوئ معلوم کړم چې زما په کلام عمل کوى او کۀ نه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1891, 'Exodus 16:5', 'Exodus', 16, 5, '&nbsp;خو په شپږمه ورځ به دوئ د هغې يو په دوه راوړى چې څومره هره ورځ راټولوى او پخوى يې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1892, 'Exodus 16:6', 'Exodus', 16, 6, '&nbsp;نو موسىٰ او هارون ټولو بنى اِسرائيلو ته وفرمائيل، ”تاسو ته به نن ماښام پته ولګى چې هغه مالِک خُدائ وو چا چې د مِصر نه راوويستلئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1893, 'Exodus 16:7', 'Exodus', 16, 7, '&nbsp;په سحر کښې به تاسو د مالِک خُدائ جلال ووينئ. مالِک خُدائ د خپل ځان خِلاف ستاسو غورېدل اورېدلى دى. مونږ هيڅ نۀ يُو چې تاسو زمونږ خِلاف غورېږئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1894, 'Exodus 16:8', 'Exodus', 16, 8, '&nbsp;بيا موسىٰ وفرمائيل، ”هغه به مالِک خُدائ وى چې په ماښام کښې تاسو له د خوړلو دپاره غوښه درکړى او په سحر کښې په مړه خېټه روټۍ درکړى، ځکه چې مالِک خُدائ د خپل ځان خِلاف ستاسو غورېدل اورېدلى دى. مونږ هيڅ هم نۀ يُو چې تاسو زمونږ خِلاف غورېږئ، دا په حقيقت کښې تاسو د مالِک خُدائ خِلاف غورېږئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1895, 'Exodus 16:9', 'Exodus', 16, 9, '&nbsp;موسىٰ هارون ته وفرمائيل، ”د بنى اِسرائيلو ټول قوم ته ووايه چې راشى او د مالِک خُدائ په حضور کښې ودريږى، ځکه چې مالِک خُدائ د دوئ غورېدل اورېدلى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1896, 'Exodus 16:10', 'Exodus', 16, 10, '&nbsp;چې هارون څنګه د بنى اِسرائيلو ټول قوم ته دا خبره وکړه او چې هغوئ بيابان ته وکتل، ناڅاپى د مالِک خُدائ جلال په وريځو کښې راښکاره شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1897, 'Exodus 16:11', 'Exodus', 16, 11, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1898, 'Exodus 16:12', 'Exodus', 16, 12, '&nbsp;”ما د بنى اِسرائيلو غورېدل اورېدلى دى. هغوئ ته ووايه چې په ماښام کښې به هغوئ ته د خوړلو دپاره غوښه مِلاو شى او سحر کښې به په روټۍ ماړۀ شى. نو هغوئ ته به پته ولګى چې زۀ مالِک خُدائ، د هغوئ خُدائ پاک يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1899, 'Exodus 16:13', 'Exodus', 16, 13, '&nbsp;په ماښام کښې د مړَزانو يو لوئ سېل راغلو او چرته چې خېمې وې هلته کښېناستو او په سحر کښې د خېمو ګېرچاپېره پرخه ورېدلې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1900, 'Exodus 16:14', 'Exodus', 16, 14, '&nbsp;چې کله پرخه اوچه شوه، نو د بيابان مخ په وړو وړو سپينو څيزونو باندې پټ شولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');